  it('post220-ultra: .github/workflows/ci.yml line[4] sha256', () => { expect(createHash('sha256').update(read(".github/workflows/ci.yml").split('\n')[4], 'utf8').digest('hex')).toBe("d746850d043eeade203d772de5cffd7224049cf5ef2e98dd6f956d48612c5616"); });
